  "title": {
    "text": "Budget Hierarchy Sunburst",
    "anchor": "middle",
    "fontSize": 18,
    "offset": 20
  },
  "signals": [
    {
      "name": "radius",
      "update": "min(width, height) / 2"
    }
  ],
  "data": [
    {
      "name": "source",
      "values": [
        {
          "program_name": "Platform",
          "subprogram_name": "Core Infra",
          "budget_kusd": 1786,
          "forecast_kusd": 1829,
          "variance_kusd": 43,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Platform",
          "subprogram_name": "Developer Tools",
          "budget_kusd": 1255,
          "forecast_kusd": 1310,
          "variance_kusd": 55,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Platform",
          "subprogram_name": "Reliability",
          "budget_kusd": 891,
          "forecast_kusd": 878,
          "variance_kusd": -13,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Growth",
          "subprogram_name": "Acquisition",
          "budget_kusd": 1333,
          "forecast_kusd": 1366,
          "variance_kusd": 33,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Growth",
          "subprogram_name": "Activation",
          "budget_kusd": 833,
          "forecast_kusd": 865,
          "variance_kusd": 32,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Growth",
          "subprogram_name": "Retention",
          "budget_kusd": 738,
          "forecast_kusd": 721,
          "variance_kusd": -17,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Enterprise",
          "subprogram_name": "Field Sales",
          "budget_kusd": 2174,
          "forecast_kusd": 2295,
          "variance_kusd": 121,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Enterprise",
          "subprogram_name": "Solutions Engineering",
          "budget_kusd": 945,
          "forecast_kusd": 1014,
          "variance_kusd": 69,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "Enterprise",
          "subprogram_name": "Enablement",
          "budget_kusd": 469,
          "forecast_kusd": 473,
          "variance_kusd": 4,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "People & Ops",
          "subprogram_name": "Hiring",
          "budget_kusd": 599,
          "forecast_kusd": 596,
          "variance_kusd": -3,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "People & Ops",
          "subprogram_name": "Learning",
          "budget_kusd": 413,
          "forecast_kusd": 424,
          "variance_kusd": 11,
          "fiscal_year": "FY2025"
        },
        {
          "program_name": "People & Ops",
          "subprogram_name": "Workplace",
          "budget_kusd": 412,
          "forecast_kusd": 408,
          "variance_kusd": -4,
          "fiscal_year": "FY2025"
        }
      ]
    },
    {
      "name": "programs",
      "source": "source",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "program_name"
          ]
        },
        {
          "type": "formula",
          "expr": "datum.program_name",
          "as": "id"
        },
        {
          "type": "formula",
          "expr": "'root'",
          "as": "parent"
        },
        {
          "type": "formula",
          "expr": "datum.program_name",
          "as": "name"
        },
        {
          "type": "formula",
          "expr": "datum.program_name",
          "as": "program"
        }
      ]
    },
    {
      "name": "subprograms",
      "source": "source",
      "transform": [
        {
          "type": "formula",
          "expr": "datum.program_name + ' - ' + datum.subprogram_name",
          "as": "id"
        },
        {
          "type": "formula",
          "expr": "datum.program_name",
          "as": "parent"
        },
        {
          "type": "formula",
          "expr": "datum.subprogram_name",
          "as": "name"
        },
        {
          "type": "formula",
          "expr": "datum.program_name",
          "as": "program"
        }
      ]
    },
    {
      "name": "root",
      "values": [
        {
          "id": "root",
          "parent": null,
          "name": "Total",
          "program": "Total"
        }
      ]
    },
    {
      "name": "tree",
      "source": [
        "root",
        "programs",
        "subprograms"
      ],
      "transform": [
        {
          "type": "stratify",
          "key": "id",
          "parentKey": "parent"
        },
        {
          "type": "partition",
          "field": "budget_kusd",
          "sort": {
            "field": "value",
            "order": "descending"
          },
          "size": [
            {
              "signal": "2 * PI"
            },
            {
              "signal": "radius"
            }
          ],
          "as": [
            "a0",
            "r0",
            "a1",
            "r1",
            "depth",
            "children"
          ]
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": {
        "data": "programs",
        "field": "program"
      },
      "range": {
        "scheme": "tableau10"
      }
    }
  ],
  "legends": [
    {
      "fill": "color",
      "title": "Program",
      "orient": "right"
    }
  ],
  "marks": [
    {
      "type": "arc",
      "from": {
        "data": "tree"
      },
      "encode": {
        "enter": {
          "x": {
            "signal": "width / 2"
          },
          "y": {
            "signal": "height / 2"
          },
          "tooltip": {
            "signal": "datum.name + ': ' + format(datum.value, ',d') + ' kUSD'"
          }
        },
        "update": {
          "fill": [
            {
              "test": "datum.id === 'root'",
              "value": "transparent"
            },
            {
              "scale": "color",
              "field": "program"
            }
          ],
          "fillOpacity": [
            {
              "test": "datum.id === 'root'",
              "value": 0
            },
            {
              "test": "datum.depth === 1",
              "value": 1
            },
            {
              "value": 0.7
            }
          ],
          "stroke": [
            {
              "test": "datum.id === 'root'",
              "value": "transparent"
            },
            {
              "value": "white"
            }
          ],
          "strokeWidth": {
            "value": 1
          },
          "startAngle": {
            "field": "a0"
          },
          "endAngle": {
            "field": "a1"
          },
          "innerRadius": {
            "field": "r0"
          },
          "outerRadius": {
            "field": "r1"
          },
          "zindex": {
            "value": 0
          }
        },
        "hover": {
          "stroke": [
            {
              "test": "datum.id === 'root'",
              "value": "transparent"
            },
            {
              "value": "black"
            }
          ],
          "strokeWidth": [
            {
              "test": "datum.id === 'root'",
              "value": 0
            },
            {
              "value": 2
            }
          ],
          "zindex": {
            "value": 1
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tree"
      },
      "encode": {
        "enter": {
          "x": {
            "signal": "width / 2"
          },
          "y": {
            "signal": "height / 2"
          },
          "text": {
            "field": "name"
          },
          "fontSize": {
            "value": 11
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "pointerEvents": {
            "value": "none"
          }
        },
        "update": {
          "radius": {
            "signal": "(datum.r0 + datum.r1) / 2"
          },
          "theta": {
            "signal": "(datum.a0 + datum.a1) / 2 - PI/2"
          },
          "angle": {
            "signal": "(datum.a0 + datum.a1) / 2 * 180 / PI - 90 + (((datum.a0 + datum.a1) / 2) > PI ? 180 : 0)"
          },
          "limit": {
            "signal": "max(0, datum.r1 - datum.r0 - 10)"
          },
          "opacity": [
            {
              "test": "datum.id === 'root'",
              "value": 0
            },
            {
              "test": "(datum.a1 - datum.a0) > 0.15",
              "value": 1
            },
            {
              "value": 0
            }
          ],
          "fill": [
            {
              "test": "datum.id === 'root'",
              "value": "transparent"
            },
            {
              "test": "datum.depth === 2",
              "value": "black"
            },
            {
              "signal": "luminance(scale('color', datum.program)) > 0.5 ? 'black' : 'white'"
            }
          ]
        }
      }
    }
  ]
}

