{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 800,
  "height": 600,
  "padding": 20,
  "title": {
    "text": "Org Structure Tree Diagram",
    "anchor": "middle",
    "fontSize": 16,
    "offset": 20
  },
  "data": [
    {
      "name": "tree",
      "url": "benchmark/package/datasets/T32.json",
      "transform": [
        {
          "type": "stratify",
          "key": "node_id",
          "parentKey": "parent_id"
        },
        {
          "type": "tree",
          "method": "tidy",
          "size": [
            {"signal": "height"},
            {"signal": "width - 200"}
          ],
          "as": ["y", "x", "depth", "children"]
        }
      ]
    },
    {
      "name": "links",
      "source": "tree",
      "transform": [
        {
          "type": "treelinks"
        },
        {
          "type": "linkpath",
          "orient": "horizontal",
          "shape": "diagonal"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "sizeScale",
      "type": "linear",
      "domain": {
        "data": "tree",
        "field": "headcount"
      },
      "range": [100, 1000],
      "zero": false
    }
  ],
  "marks": [
    {
      "type": "path",
      "from": {
        "data": "links"
      },
      "encode": {
        "update": {
          "path": {
            "field": "path"
          },
          "stroke": {
            "value": "#ccc"
          },
          "strokeWidth": {
            "value": 1.5
          },
          "fill": {
            "value": "none"
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "tree"
      },
      "encode": {
        "update": {
          "x": {
            "field": "x"
          },
          "y": {
            "field": "y"
          },
          "size": {
            "scale": "sizeScale",
            "field": "headcount"
          },
          "shape": {
            "value": "circle"
          },
          "fill": {
            "value": "steelblue"
          },
          "stroke": {
            "value": "white"
          },
          "strokeWidth": {
            "value": 1.5
          },
          "zindex": {
            "value": 1
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tree"
      },
      "encode": {
        "update": {
          "x": {
            "field": "x"
          },
          "y": {
            "field": "y"
          },
          "dx": {
            "signal": "datum.children ? -20 : 20"
          },
          "dy": {
            "value": 0
          },
          "align": {
            "signal": "datum.children ? 'right' : 'left'"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "field": "role_name"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#333"
          },
          "zindex": {
            "value": 2
          }
        }
      }
    }
  ]
}

