      "orient": "left",
      "scale": "y",
      "title": "Measurement Value",
      "labelFontSize": 12,
      "titleFontSize": 14
    }
  ],
  "marks": [
    {
      "type": "group",
      "from": {
        "facet": {
          "data": "density",
          "name": "violin",
          "groupby": "sensor_type"
        }
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "field": "sensor_type"
          },
          "width": {
            "signal": "bandwidth('x')"
          },
          "y": {
            "value": 0
          },
          "height": {
            "signal": "height"
          }
        }
      },
      "marks": [
        {
          "type": "area",
          "from": {
            "data": "violin"
          },
          "encode": {
            "enter": {
              "orient": {
                "value": "horizontal"
              },
              "interpolate": {
                "value": "monotone"
              },
              "fill": {
                "scale": "color",
                "field": {
                  "parent": "sensor_type"
                }
              },
              "fillOpacity": {
                "value": 0.7
              },
              "y": {
                "scale": "y",
                "field": "value"
              },
              "x": {
                "signal": "width / 2 - scale('w', datum.norm_density) / 2"
              },
              "x2": {
                "signal": "width / 2 + scale('w', datum.norm_density) / 2"
              }
            }
          }
        }
      ]
    }
  ]
}

