    {
      "name": "segments",
      "source": "table",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "segment_name"
          ],
          "fields": [
            "segment_size_pct"
          ],
          "ops": [
            "max"
          ],
          "as": [
            "width"
          ]
        },
        {
          "type": "window",
          "ops": [
            "sum"
          ],
          "fields": [
            "width"
          ],
          "as": [
            "x1"
          ],
          "sort": {
            "field": "width",
            "order": "descending"
          }
        },
        {
          "type": "formula",
          "expr": "datum.x1 - datum.width",
          "as": "x0"
        }
      ]
    },
    {
      "name": "marks_data",
      "source": "table",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "segment_name",
            "brand_name"
          ],
          "fields": [
            "share_pct"
          ],
          "ops": [
            "sum"
          ],
          "as": [
            "height"
          ]
        },
        {
          "type": "lookup",
          "from": "segments",
          "key": "segment_name",
          "fields": [
            "segment_name"
          ],
          "values": [
            "x0",
            "x1"
          ]
        },
        {
          "type": "window",
          "ops": [
            "sum"
          ],
          "fields": [
            "height"
          ],
          "as": [
            "y1"
          ],
          "groupby": [
            "segment_name"
          ],
          "sort": {
            "field": "brand_name"
          }
        },
        {
          "type": "formula",
          "expr": "datum.y1 - datum.height",
          "as": "y0"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "linear",
      "domain": {
        "data": "segments",
        "field": "x1"
      },
      "range": "width",
      "zero": true
    },
    {
      "name": "y",
      "type": "linear",
      "domain": {
        "data": "marks_data",
        "field": "y1"
      },
      "range": "height",
      "zero": true,
      "nice": true
    },
    {
      "name": "color",
