          "x": {
            "scale": "x",
            "field": "x0"
          },
          "x2": {
            "scale": "x",
            "field": "x1"
          },
          "y": {
            "scale": "y",
            "field": "y0"
          },
          "y2": {
            "scale": "y",
            "field": "y1"
          },
          "fill": {
            "scale": "color",
            "field": "brand_name"
          },
          "stroke": {
            "value": "white"
          },
          "strokeWidth": {
            "value": 1
          },
          "tooltip": {
            "signal": "{'Segment': datum.segment_name, 'Brand': datum.brand_name, 'Share (%)': datum.height, 'Segment Size (%)': datum.x1 - datum.x0}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "segments"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "signal": "(datum.x0 + datum.x1) / 2"
          },
          "y": {
            "signal": "height + 20"
          },
          "text": {
            "field": "segment_name"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "top"
          },
          "fill": {
            "value": "black"
          },
          "fontSize": {
            "value": 11"
          },
          "limit": {
            "signal": "max(0, scale('x', datum.x1) - scale('x', datum.x0) - 4)"
          }
        }
      }
    }
  ]
}

