results.rawResponse:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Vehicle Specs Parallel Coordinates",
  "data": {
    "url": "benchmark/package/datasets/T34.json"
  },
  "width": 600,
  "height": 400,
  "transform": [
    {
      "fold": [
        "mpg",
        "horsepower",
        "weight_kg",
        "acceleration_s"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "value",
          "as": "min"
        },
        {
          "op": "max",
          "field": "value",
          "as": "max"
        }
      ],
      "groupby": [
        "key"
      ]
    },
    {
      "calculate": "(datum.value - datum.min) / (datum.max - datum.min)",
      "as": "norm_val"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#ccc"
      },
      "encoding": {
        "detail": {
          "aggregate": "count"
        },
        "x": {
          "field": "key",
          "type": "nominal"
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "opacity": 0.8
      },
      "encoding": {
        "x": {
          "field": "key",
          "type": "nominal",
          "title": null,
          "axis": {
            "labelAngle": 0,
            "domain": false,
            "tickColor": "#ccc"
          }
        },
        "y": {
          "field": "norm_val",
          "type": "quantitative",
          "axis": null
        },
        "color": {
          "field": "origin",
          "type": "nominal",
          "scale": {
            "domain": [
              "USA",
              "Europe",
              "Asia"
            ],
            "range": [
              "#4c78a8",
              "#f58518",
              "#54a24b"
            ]
          },
          "legend": {
            "title": "Origin"
          }
        },
        "detail": {
          "field": "model_name",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "model_name",
            "type": "nominal",
            "title": "Model"
          },
          {
            "field": "origin",
            "type": "nominal",
            "title": "Origin"
          },
          {
            "field": "key",
            "type": "nominal",
            "title": "Metric"
          },
          {
            "field": "value",
            "type": "quantitative",
            "title": "Value"
          }
        ]
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    }
  }
}

